contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to_, uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0);
        require(amount_ > 0);

        c.requestLoan(amount_, interest_, loanToCollateral_, duration_); if (__ESBMC_reverted()) return;
        c.clearRequest(0, false, false); if (__ESBMC_reverted()) return;

        c.approveTransfer(to_, 0); if (__ESBMC_reverted()) return;
        address approved = c.approvals(0); if (__ESBMC_reverted()) return;

        assert(approved == to_);
    }

    receive() external payable {}
}

