pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(address to_, uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) internal {
        vm.assume(loanToCollateral_ != 0);
        vm.assume(amount_ > 0);
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {} catch { return; }
        try c.clearRequest(0, false, false) {} catch { return; }
        try c.approveTransfer(to_, 0) {} catch { return; }
        address approved;
        try c.approvals(0) returns (address __r) { approved = __r; } catch { return; }
        assertTrue(approved == to_);
    }

    function testFuzz_run(address to_, uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public {
        vm.assume(to_.code.length == 0 && uint160(to_) > 0xffff && to_ != address(this) && to_ != address(c) && to_ != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to_ != 0x000000000000000000636F6e736F6c652e6c6f67 && to_ != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to_ != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(to_, amount_, interest_, loanToCollateral_, duration_);
    }

    receive() external payable {}
}
